import{z as B,x as A,o as s,c as d,q as n,j as i,D as e,d as E,s as l,S as o,b as t}from"./chunks/framework.C8m1ZpeB.js";const u=JSON.parse('{"title":"时钟树与抖动","description":"","frontmatter":{"title":"时钟树与抖动","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/clock-jitter.md","filePath":"cs/clock-jitter.md","lastUpdated":1791063341000}'),p={name:"cs/clock-jitter.md"};function F(c,a,D,m,C,h){const r=A("Mermaid");return s(),d("div",null,[a[2]||(a[2]=n('<h1 id="时钟树与抖动" tabindex="-1">时钟树与抖动 <a class="header-anchor" href="#时钟树与抖动" aria-label="Permalink to &quot;时钟树与抖动&quot;">​</a></h1><div class="epigraph"><p>理想边沿同时到达每个触发器；铜线上的树有偏斜，振荡器有抖动，建立保持不等式里的 $T$ 与 skew 都要加这两项。</p><footer>—— 据 Harris and Harris, Digital Design and Computer Architecture；Patterson and Hennessy, Computer Organization and Design (RISC-V) 整理</footer></div><p>上一课<a href="/cs/clock-domain">时钟域</a>钉死了跨域必须同步。本课不重画两级 FF，也不从锁相环环路方程另起。缺口是<strong>同一域内部</strong>：时钟不是一根零延迟的线。树的不平衡叫偏斜，边沿在周期间晃叫抖动；它们改写<a href="/cs/setup-hold">建立保持</a>已经写下的那一项 skew。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>时钟从源走到各 FF 的延迟不同，\\(\\Delta\\) 即 skew。最坏建立：\\(T\\ge t_{cq}+t_{pd}+t_{su}+\\Delta_{\\mathrm{worst}}\\)；保持更怕时钟早到接收端。抖动：周期不是常数，\\(T\\) 要用有效最小周期。缺口不是再定义域，而是把「理想同源边沿」换成带 \\(\\Delta\\) 与 jitter 的同源。<span class="marginnote">术语翻译：skew 是「空间上的不同步」——同一根时钟到各触发器的铜线有长有短，先到后到固定差一截；jitter 是「时间上的不稳」——同一条路径上每一拍的边沿位置都在小幅晃动。一个按地点分误差，一个按拍次分误差，所以不等式里要分别记两项。</span></p><p>时钟树用缓冲器做成 H 树或网格，目的是减小 skew，自己也贡献延迟与功耗。门控时钟是树上的开关，须当新的时序弧。</p><h3 id="抖动不是亚稳" tabindex="-1">抖动不是亚稳 <a class="header-anchor" href="#抖动不是亚稳" aria-label="Permalink to &quot;抖动不是亚稳&quot;">​</a></h3><p>亚稳是数据相对边沿落在窗口内。抖动是边沿自己在时间轴上晃，让窗口相对数据移动。用同步器修不了树上的 skew；那是布局与树设计。</p><p><span class="marginnote">Harris 把 clock skew 写进不等式。Patterson/Hennessy 讨论时钟与周期。本课不把晶振相位噪声谱写成通信课。PLL 只承认「把高频时钟干净地送给树」。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>STA：每条 FF→组合→FF 弧带时钟到达时间。插入延迟可修保持（让数据更晚或时钟关系改变），可能伤建立。教学 CPU 仍可假设 skew=0，但组成主干记得 \\(T\\) 含裕量。<span class="marginnote">数字实例：目标主频 1 GHz，周期 1 ns；若树的不平衡贡献 0.15 ns 的最坏 skew、抖动又吃掉 0.05 ns，留给组合逻辑与建立时间的预算就只剩约 0.8 ns。主频不是标称出来的，是先付完这些「时钟税」再谈的。</span></p>',11)),(s(),i(o,null,{default:e(()=>[l(r,{id:"mermaid-31",class:"mermaid",graph:"flowchart%20TD%0A%20%20SRC%5B%22%E6%97%B6%E9%92%9F%E6%BA%90%22%5D%20--%3E%20TREE%5B%22%E7%BC%93%E5%86%B2%E6%A0%91%20%2F%20%E7%BD%91%E6%A0%BC%22%5D%0A%20%20TREE%20--%3E%20FF%5B%22%E5%90%84%E8%A7%A6%E5%8F%91%E5%99%A8%E8%BE%B9%E6%B2%BF%22%5D%0A%20%20FF%20--%3E%20SKEW%5B%22skew%20%E8%BF%9B%E5%85%A5%E5%BB%BA%E7%AB%8B%E4%BF%9D%E6%8C%81%22%5D%0A%20%20SKEW%20--%3E%20LATER%5B%22%E5%90%8E%E8%AF%BE%EF%BC%9A%E5%AD%98%E5%82%A8%E7%A8%8B%E5%BA%8F%22%5D%0A"})]),fallback:e(()=>[...a[0]||(a[0]=[E(" Loading... ",-1)])]),_:1})),a[3]||(a[3]=t("h2",{id:"机制",tabindex:"-1"},[E("机制 "),t("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),a[4]||(a[4]=t("p",null,[E("门、寄存器、阵列、跨域同步已经齐。同步数字块的时间边界本课收束：同域靠树与不等式，跨域靠上一课。下一课不再加时钟元件，而是把"),t("strong",null,"指令比特"),E("放进存储器——硬件已经够跑存储程序。")],-1)),(s(),i(o,null,{default:e(()=>[l(r,{id:"mermaid-38",class:"mermaid",graph:"flowchart%20TD%0A%20%20EDGE%5B%22%E5%90%8C%E4%B8%80%E6%9D%A1%E6%95%B0%E6%8D%AE%E8%B7%AF%E5%BE%84%E7%9A%84%E4%B8%A4%E7%AB%AF%22%5D%20--%3E%20Q%7B%22%E6%8D%95%E8%8E%B7%E7%AB%AF%E6%97%B6%E9%92%9F%E7%9B%B8%E5%AF%B9%E5%8F%91%E9%80%81%E7%AB%AF%E5%81%8F%E6%97%A9%E8%BF%98%E6%98%AF%E5%81%8F%E6%99%9A%EF%BC%9F%22%7D%0A%20%20Q%20--%3E%7C%22%E5%81%8F%E6%99%9A%22%7C%20SETUP%5B%22%E6%9C%89%E6%95%88%E5%91%A8%E6%9C%9F%E8%A2%AB%E5%89%8A%E7%9F%AD%EF%BC%8C%E5%BB%BA%E7%AB%8B%E8%A3%95%E9%87%8F%E8%A2%AB%E5%92%AC%22%5D%0A%20%20Q%20--%3E%7C%22%E5%81%8F%E6%97%A9%22%7C%20HOLD%5B%22%E6%96%B0%E6%95%B0%E6%8D%AE%E5%86%B2%E6%8E%89%E6%97%A7%E5%80%BC%E8%BF%98%E6%B2%A1%E9%94%81%E4%BD%8F%EF%BC%8C%E4%BF%9D%E6%8C%81%E8%A2%AB%E5%92%AC%22%5D%0A%20%20SETUP%20--%3E%20BUD%5B%22%E6%8C%89%E6%9C%80%E5%9D%8F%E6%96%B9%E5%90%91%E6%8A%8A%20skew%20%E8%AE%A1%E5%85%A5%20T%22%5D%0A%20%20HOLD%20--%3E%20FIX%5B%22%E6%8F%92%E5%BB%B6%E8%BF%9F%E4%BF%AE%E4%BF%9D%E6%8C%81%EF%BC%8C%E4%BD%86%E8%A6%81%E5%A4%8D%E6%9F%A5%E5%BB%BA%E7%AB%8B%22%5D%0A"})]),fallback:e(()=>[...a[1]||(a[1]=[E(" Loading... ",-1)])]),_:1})),a[5]||(a[5]=n('<p><span class="marginnote">这张图回答「skew 的方向为什么决定咬的是建立还是保持」。初学者容易把两者混为一谈：建立是「这一拍来得及吗」，怕捕获端时钟晚到；保持是「旧值锁住了吗」，怕捕获端时钟早到。同一份树不平衡，方向不同，症状完全相反。</span></p><p><span class="marginnote">常见误区：发现保持违例就想着提频或换更快的触发器——方向反了。保持检查关心的是同一拍内的竞争，与时钟周期长短无关，提频救不了；标准修法是让数据路上多绕一点（插入延迟），修完还要回头复查建立有没有被挤坏。</span></p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不讲源同步 DDR 的 DQS、不把无线时钟恢复请进来。全异步设计不靠本课的树。</p><p>后课默认：教学图可画一根理想 clk；真实周期含 skew 与 jitter 裕量。下一课开始：算法变成内存里的指令。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>时钟树引入 skew；抖动侵蚀有效 \\(T\\)。</li><li>建立保持要把这两项算进裕量。</li><li>同步硬件边界到此；下一课存储程序。</li><li>出处：Harris and Harris；Patterson and Hennessy, COD (RISC-V)。</li></ul>',7))])}const _=B(p,[["render",F]]);export{u as __pageData,_ as default};
